<?php

declare(strict_types=1);

namespace Rustine\Tests\Apply;

use PHPUnit\Framework\Attributes\Test;
use PHPUnit\Framework\TestCase;
use Rustine\Apply\YarnClassicLockfile;

final class YarnClassicLockfileTest extends TestCase
{
    private const LOCK = <<<'LOCK'
        # THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.
        # yarn lockfile v1


        "@scope/braces@^2.0.0", "@scope/braces@^2.1.0":
          version "2.1.0"
          resolved "https://registry.yarnpkg.com/@scope/braces/-/braces-2.1.0.tgz#abc"

        braces@^3.0.2, braces@~3.0.0:
          version "3.0.2"
          resolved "https://registry.yarnpkg.com/braces/-/braces-3.0.2.tgz#def"
          dependencies:
            fill-range "^7.0.1"

        "braces@^2.3.1":
          version "2.3.2"

        fill-range@^7.0.1:
          version "7.0.1"
          dependencies:
            braces "^3.0.2"

        mkdirp@0.5.1:
          version "0.5.1"

        LOCK;

    #[Test]
    public function itRemovesEveryBlockOfThePackageWhateverTheSpecifierStyle(): void
    {
        $result = (new YarnClassicLockfile())->withoutPackage(self::LOCK, 'braces');

        self::assertStringNotContainsString('version "3.0.2"', $result);
        self::assertStringNotContainsString('version "2.3.2"', $result);
        self::assertStringContainsString('fill-range@^7.0.1:', $result);
        self::assertStringContainsString('mkdirp@0.5.1:', $result);
    }

    #[Test]
    public function aLockfileWithCrlfLineEndingsIsEditedAndKeepsThem(): void
    {
        $crlf = str_replace("\n", "\r\n", self::LOCK);

        $result = (new YarnClassicLockfile())->withoutPackage($crlf, 'braces');

        self::assertSame(str_replace("\n", "\r\n", (new YarnClassicLockfile())->withoutPackage(self::LOCK, 'braces')), $result);
        self::assertStringNotContainsString('version "3.0.2"', $result);
        self::assertStringNotContainsString("\n\n", str_replace("\r\n", '', $result));
    }

    #[Test]
    public function itKeepsScopedPackagesWithTheSameBaseName(): void
    {
        $result = (new YarnClassicLockfile())->withoutPackage(self::LOCK, 'braces');

        self::assertStringContainsString('"@scope/braces@^2.0.0", "@scope/braces@^2.1.0":', $result);
    }

    #[Test]
    public function itRemovesAScopedPackage(): void
    {
        $result = (new YarnClassicLockfile())->withoutPackage(self::LOCK, '@scope/braces');

        self::assertStringNotContainsString('@scope/braces', $result);
        self::assertStringContainsString('braces@^3.0.2, braces@~3.0.0:', $result);
    }

    #[Test]
    public function referencesInsideOtherBlocksAreLeftAlone(): void
    {
        $result = (new YarnClassicLockfile())->withoutPackage(self::LOCK, 'braces');

        self::assertStringContainsString('braces "^3.0.2"', $result);
    }

    #[Test]
    public function itKeepsTheHeaderAndTheFinalNewlineEvenWhenTheLastBlockGoes(): void
    {
        $result = (new YarnClassicLockfile())->withoutPackage(self::LOCK, 'mkdirp');

        self::assertStringStartsWith("# THIS IS AN AUTOGENERATED FILE.", $result);
        self::assertStringEndsWith("\n", $result);
        self::assertStringNotContainsString('mkdirp', $result);
    }

    #[Test]
    public function aMissingPackageLeavesTheFileUntouched(): void
    {
        self::assertSame(self::LOCK, (new YarnClassicLockfile())->withoutPackage(self::LOCK, 'nope'));
    }
}
